//! `receipts.toml`: GENERATED by `case_fetch.py verify`, never hand-edited
//! (docs/FORENSIC_CASE_STUDIES_PLAN.md §4.4). One `[[receipt]]` per sourced
//! fact records where its quote was found, the hashes it was bound by, and
//! the four binding booleans.

use fa_registry::toml::{Document, Table, Value as TomlValue};

use super::error::{LoadError, LoadErrorKind};
use super::fields::{Row, is_sha256_hex};
use super::rows::row_line;
use super::source::{closed, put};

closed_set! {
    /// How the fact was bound: sentence alignment for prose anchors, exact
    /// value for table cells, XBRL facts and exhibits (§4.1).
    Alignment {
        Sentence => "sentence",
        Value => "value",
    }
}

/// One `[[receipt]]` row.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Receipt {
    pub source: String,
    pub fact: String,
    /// Where the quote was found (K-ANCHOR checks it lies inside the fact's
    /// declared anchor).
    pub anchor: String,
    /// The cache entry's fetch time, not the run's clock, so a re-run on an
    /// unchanged cache is byte-identical.
    pub verified_utc: String,
    pub tool_version: String,
    pub extraction_sha256: String,
    pub quote_sha256: String,
    pub values_sha256: String,
    pub alignment: Alignment,
    pub quote_found_once: bool,
    pub aligned: bool,
    pub values_in_quote: bool,
    pub scope_ok: bool,
    /// Copied from the source's row (false for an archive capture until
    /// owner decision 1 allows an original fetch).
    pub original_hash_compared: bool,
    pub line: Option<usize>,
}

impl Receipt {
    /// Whether all four binding booleans hold.
    #[must_use]
    pub const fn binds(&self) -> bool {
        self.quote_found_once && self.aligned && self.values_in_quote && self.scope_ok
    }
}

pub(crate) fn parse_rows(
    file: &str,
    text: &str,
    rows: &[Table],
    errs: &mut Vec<LoadError>,
) -> Vec<Receipt> {
    let mut out = Vec::with_capacity(rows.len());
    for (i, table) in rows.iter().enumerate() {
        let fact_id = table
            .get("fact")
            .and_then(TomlValue::as_str)
            .map(str::to_string);
        let mut r = Row::new(file, row_line(text, "receipt", i), table).with_id(fact_id);
        let source = r.req_str("source", errs);
        let fact = r.req_str("fact", errs);
        let anchor = r.req_str("anchor", errs);
        let verified_utc = r.req_str("verified_utc", errs);
        let tool_version = r.req_str("tool_version", errs);
        let extraction_sha256 = r.req_str("extraction_sha256", errs);
        let quote_sha256 = r.req_str("quote_sha256", errs);
        let values_sha256 = r.req_str("values_sha256", errs);
        let alignment_raw = r.req_str("alignment", errs);
        let quote_found_once = r.req_bool("quote_found_once", errs);
        let aligned = r.req_bool("aligned", errs);
        let values_in_quote = r.req_bool("values_in_quote", errs);
        let scope_ok = r.req_bool("scope_ok", errs);
        let original_hash_compared = r.req_bool("original_hash_compared", errs);
        r.finish(&[], "", errs);
        let alignment = closed(&r, "alignment", &alignment_raw, Alignment::parse, errs)
            .unwrap_or(Alignment::Sentence);
        for (key, value) in [
            ("extraction_sha256", &extraction_sha256),
            ("quote_sha256", &quote_sha256),
            ("values_sha256", &values_sha256),
        ] {
            if !value.is_empty() && !is_sha256_hex(value) {
                errs.push(r.err(
                    LoadErrorKind::NotSha256Hex,
                    format!("`{key}` must be 64 lower-case hex characters"),
                ));
            }
        }
        out.push(Receipt {
            source,
            fact,
            anchor,
            verified_utc,
            tool_version,
            extraction_sha256,
            quote_sha256,
            values_sha256,
            alignment,
            quote_found_once,
            aligned,
            values_in_quote,
            scope_ok,
            original_hash_compared,
            line: r.line(),
        });
    }
    out
}

impl Receipt {
    /// The row as the TOML subset's table.
    #[must_use]
    pub fn to_table(&self) -> Table {
        let mut t = Table::new();
        put(&mut t, "source", &self.source);
        put(&mut t, "fact", &self.fact);
        put(&mut t, "anchor", &self.anchor);
        put(&mut t, "verified_utc", &self.verified_utc);
        put(&mut t, "tool_version", &self.tool_version);
        put(&mut t, "extraction_sha256", &self.extraction_sha256);
        put(&mut t, "quote_sha256", &self.quote_sha256);
        put(&mut t, "values_sha256", &self.values_sha256);
        put(&mut t, "alignment", self.alignment.as_str());
        for (key, b) in [
            ("quote_found_once", self.quote_found_once),
            ("aligned", self.aligned),
            ("values_in_quote", self.values_in_quote),
            ("scope_ok", self.scope_ok),
            ("original_hash_compared", self.original_hash_compared),
        ] {
            t.insert(key.into(), TomlValue::Bool(b));
        }
        t
    }
}

/// `receipts.toml` as a document.
#[must_use]
pub fn to_document(receipts: &[Receipt]) -> Document {
    let mut doc = Document::default();
    if !receipts.is_empty() {
        doc.arrays.insert(
            "receipt".into(),
            receipts.iter().map(Receipt::to_table).collect(),
        );
    }
    doc
}
